package com.novara.banking.servicerequest;
import com.novara.banking.audit.AuditService;import com.novara.banking.identity.CurrentIdentity.FederatedIdentity;import com.novara.banking.shared.DomainException;import org.slf4j.MDC;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.Instant;import java.util.*;
@Service public class ServiceRequestService{
 private final JdbcClient jdbc;private final AuditService audit;public ServiceRequestService(JdbcClient j,AuditService a){jdbc=j;audit=a;}
 public Page page(FederatedIdentity i,int page,int size,String search,String sort){String term=search==null?"":search.trim().toLowerCase(Locale.ROOT);String order="oldest".equals(sort)?"ASC":"DESC";long total=jdbc.sql("SELECT count(*) FROM service_requests r JOIN customers c ON c.id=r.customer_id WHERE c.identity_issuer=:issuer AND c.identity_subject=:subject AND (:search='' OR lower(r.description) LIKE :pattern OR lower(r.category) LIKE :pattern)").param("issuer",i.issuer()).param("subject",i.subject()).param("search",term).param("pattern","%"+term+"%").query(Long.class).single();List<View> items=jdbc.sql(BASE+" AND (:search='' OR lower(r.description) LIKE :pattern OR lower(r.category) LIKE :pattern) ORDER BY r.created_at "+order+",r.id "+order+" LIMIT :size OFFSET :offset").param("issuer",i.issuer()).param("subject",i.subject()).param("search",term).param("pattern","%"+term+"%").param("size",size).param("offset",page*size).query(this::map).list();return new Page(items,page,size,total,(total+size-1)/size);}
 public View one(FederatedIdentity i,UUID id){return jdbc.sql(BASE+" AND r.public_id=:id").param("issuer",i.issuer()).param("subject",i.subject()).param("id",id).query(this::map).optional().orElseThrow(this::missing);}
 public List<Event> history(FederatedIdentity i,UUID id){one(i,id);return jdbc.sql("SELECT e.status::text,e.customer_visible_message,e.occurred_at FROM service_request_status_events e JOIN service_requests r ON r.id=e.service_request_id WHERE r.public_id=:id ORDER BY e.occurred_at,e.id").param("id",id).query((r,n)->new Event(r.getString(1),r.getString(2),r.getTimestamp(3).toInstant())).list();}
 @Transactional public View create(FederatedIdentity i,Create request,String key){if(key==null||!key.matches("[A-Za-z0-9._-]{16,100}"))throw new DomainException(HttpStatus.BAD_REQUEST,"IDEMPOTENCY_KEY_REQUIRED","A valid Idempotency-Key is required.");long customer=customer(i);String description=request.description().trim();if(description.matches("(?is).*\\b(password|passcode|otp|pin|recovery\\s+code)\\b.*"))throw new DomainException(HttpStatus.UNPROCESSABLE_ENTITY,"SENSITIVE_DESCRIPTION","Remove passwords, PINs, OTPs, passcodes, or recovery codes from the description.");String hash=hash(request.category()+"|"+description);jdbc.sql("SELECT 1 FROM pg_advisory_xact_lock(hashtextextended(:lock,0))").param("lock","service-request:"+customer+":"+key).query(Long.class).single();var existing=jdbc.sql("SELECT public_id,request_hash FROM service_requests WHERE customer_id=:c AND idempotency_key=:key").param("c",customer).param("key",key).query((r,n)->Map.entry(r.getObject(1,UUID.class),r.getString(2))).optional();if(existing.isPresent()){if(!existing.get().getValue().equals(hash))throw new DomainException(HttpStatus.CONFLICT,"IDEMPOTENCY_CONFLICT","This key was already used for a different request.");return one(i,existing.get().getKey());}UUID id=jdbc.sql("INSERT INTO service_requests(customer_id,category,description,idempotency_key,request_hash) VALUES(:c,:category,:description,:key,:hash) RETURNING public_id").param("c",customer).param("category",request.category()).param("description",description).param("key",key).param("hash",hash).query(UUID.class).single();jdbc.sql("INSERT INTO service_request_status_events(service_request_id,status,customer_visible_message) SELECT id,'SUBMITTED','Your request has been securely received.' FROM service_requests WHERE public_id=:id").param("id",id).update();jdbc.sql("INSERT INTO customer_notifications(customer_id,type,title,message,navigation_target,source_event_id) SELECT :c,'SERVICE_REQUEST','Service request submitted','Your service request has been received.','/account-services/requests/'||CAST(:id AS text),:id WHERE COALESCE((SELECT p.service_requests FROM notification_preferences p WHERE p.customer_id=:c),true) ON CONFLICT DO NOTHING").param("c",customer).param("id",id).update();audit.record(i.subject(),"SERVICE_REQUEST_SUBMITTED","SERVICE_REQUEST",id,"SUCCESS",MDC.get("correlationId"),"{}");return one(i,id);}
 private long customer(FederatedIdentity i){return jdbc.sql("SELECT id FROM customers WHERE identity_issuer=:issuer AND identity_subject=:subject AND status='ACTIVE'").param("issuer",i.issuer()).param("subject",i.subject()).query(Long.class).optional().orElseThrow(this::missing);}
 private View map(java.sql.ResultSet r,int n)throws java.sql.SQLException{return new View(r.getObject(1,UUID.class),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getTimestamp(6).toInstant(),r.getTimestamp(7).toInstant());}
 private DomainException missing(){return new DomainException(HttpStatus.NOT_FOUND,"SERVICE_REQUEST_NOT_FOUND","The service request was not found.");}
 private String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private static final String BASE="SELECT r.public_id,r.category,r.description,r.status::text,r.customer_visible_response,r.created_at,r.updated_at FROM service_requests r JOIN customers c ON c.id=r.customer_id WHERE c.identity_issuer=:issuer AND c.identity_subject=:subject";
 public record Create(@jakarta.validation.constraints.Pattern(regexp="ACCOUNT_INFORMATION|STATEMENT_ASSISTANCE|CONTACT_UPDATE_ASSISTANCE|CARD_SUPPORT|GENERAL_ACCOUNT_SUPPORT") String category,@jakarta.validation.constraints.Size(min=10,max=500) String description){}
 public record View(UUID id,String category,String description,String status,String response,Instant createdAt,Instant updatedAt){} public record Event(String status,String message,Instant occurredAt){} public record Page(List<View> items,int page,int size,long totalElements,long totalPages){}
}
